/*
d = a_b + a_c
                where
                a  ∈ ℝ^3
                b  ∈ ℤ
                c  ∈ ℤ index
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT d;

    heartlib(
        const Eigen::Matrix<double, 3, 1> & a,
        const int & b,
        const int & c)
    {

        // d = a_b + a_c
        d = a[b-1] + a[c];
    }
};

