function output = heartlib(a, b, c)
% output = heartlib(a, b, c)
%
%    d = a_b + a_c
%                    where
%                    a  ∈ ℝ^3
%                    b  ∈ ℤ
%                    c  ∈ ℤ index
    a = reshape(a,[],1);

    assert( numel(a) == 3 );
    assert(numel(b) == 1);
    assert(numel(c) == 1);

    % d = a_b + a_c

    d = a(b) + a(c);
    output.d = d;
end

